  await new Promise((r) => setImmediate(r));
  assert.equal(requested, 1, "review mode prompts even for safe reads");
  const pending = ctl.listPending()[0]!;
  assert.equal(ctl.resolveApproval(pending.approvalId, true), true);
  await review;

  ctl.setMode("default");
